INSERT INTO t_p98221464_innovative_solution_.materials (name, category, price, unit, description, image_url, in_stock, sort_order)
VALUES ('Стеновой блок Поритеп D500 625×300×200', 'bloki', '5 700 ₽', 'м³', 'Производство «Поритеп». Размер 625×300×200 мм (длина × толщина × высота). Плотность D500. В упаковке (на поддоне) 1,875 м³ — 50 шт. Класс прочности B3,5, морозостойкость F100, огнестойкость REI360. Теплопроводность λ₀ 0,12 Вт/(м·°C), паропроницаемость 0,23 мг/(м·ч·Па), усадка 0,24 мм/м. В 1 м³ — 26,7 блоков, на 1 м² стены — 8 блоков. Монтажный вес блока 23,4 кг. Тёплые несущие стены под кладку на клей. Доставка манипулятором с разгрузкой.', '/img/gazoblok-625-300-200-poritep.jpg', true, 1);